"use client";

import "../../styles/teum-base.css";
import "../../styles/components/kbd.css";
import type { ComponentPropsWithRef } from "react";
import { cn } from "../../lib/cn";

export type KbdProps = ComponentPropsWithRef<"kbd">;

export function Kbd({ className, ...props }: KbdProps) {
  return <kbd className={cn("teum-kbd", className)} {...props} />;
}

export type KbdGroupProps = ComponentPropsWithRef<"span">;

export function KbdGroup({ className, ...props }: KbdGroupProps) {
  return <span className={cn("teum-kbd-group", className)} {...props} />;
}

/* Generated from src/styles.css. Do not edit directly. */

@layer teum.tokens, teum.base, teum.components;

@layer teum.components {
.teum-kbd-group { display: inline-flex; align-items: center; gap: 3px; color: var(--teum-fg-muted); font-size: 11px; white-space: nowrap; }

.teum-kbd {
  display: inline-flex;
  min-width: 20px;
  height: 20px;
  align-items: center;
  justify-content: center;
  padding: 0 5px;
  border: 0;
  border-radius: 4px;
  background: var(--teum-bg-subtle);
  box-shadow: inset 0 0 0 1px var(--teum-separator), 0 1px 0 color-mix(in oklch, var(--teum-fg-default) 8%, transparent);
  color: var(--teum-fg-muted);
  font-family: var(--teum-font-code);
  font-size: 10.5px;
  font-weight: 500;
  line-height: 1;
  white-space: nowrap;
}
}
